text = '\n'.join(lines)
for anchor, img, cap in IMG:
    if '\n' in anchor:
        a1, a2 = anchor.split('\n')
        k = text.find(a1)
        assert k >= 0, anchor
        e = text.find('\n', k)
        text = text[:e] + f'\n@IMG|{img}|{cap}' + text[e:]
        continue
    k = text.find(anchor)
    if k < 0:
        sys.exit('MISSING image anchor: ' + anchor)
    e = text.find('\n', k)
    text = text[:e] + f'\n@IMG|{img}|{cap}' + text[e:]
open(D + 'novel2.txt', 'w', encoding='utf-8').write(text)
json.dump(fnotes, open(D + 'footnotes.json', 'w', encoding='utf-8'), ensure_ascii=False, indent=0)
print('footnotes:', len(fnotes))
